using System.ComponentModel.DataAnnotations;using LocalPro.Web.Domain;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace LocalPro.Web.Pages.Account;
public class RegisterModel(UserManager<AppUser> users,SignInManager<AppUser> signIn):PageModel{
 [BindProperty,Required,StringLength(100)]public string Name{get;set;}="";[BindProperty,Required,EmailAddress]public string Email{get;set;}="";[BindProperty,Required,MinLength(10)]public string Password{get;set;}="";[BindProperty]public bool Terms{get;set;}
 public async Task<IActionResult> OnPostAsync(){if(!Terms)ModelState.AddModelError("","Accept the service terms to continue.");if(!ModelState.IsValid)return Page();var u=new AppUser{UserName=Email,Email=Email,DisplayName=Name.Trim()};var result=await users.CreateAsync(u,Password);if(result.Succeeded){await signIn.SignInAsync(u,false);return RedirectToPage("/Index");}foreach(var e in result.Errors)ModelState.AddModelError("",e.Description);return Page();}}
